<div style="text-align:center;margin-bottom:18px;"><?php $logo=get_option('company_logo_dark')?:get_option('company_logo'); if($logo): ?><img src="<?php echo FCPATH.'uploads/company/'.$logo; ?>" style="max-width:220px;max-height:75px;"><?php endif; ?><h1><?php echo _l('solar_pro_your_solar_report'); ?> #<?php echo (int)$analysis['id']; ?></h1><p><?php echo html_escape(trim($analysis['first_name'].' '.$analysis['last_name'])); ?> — <?php echo html_escape($analysis['address']); ?></p></div>
<table cellpadding="7" border="1"><tr><td><b><?php echo _l('solar_pro_system_size'); ?></b><br><?php echo number_format($analysis['system_kw'],3); ?> kW</td><td><b><?php echo _l('solar_pro_panels'); ?></b><br><?php echo (int)$analysis['panel_count']; ?> × <?php echo number_format($analysis['panel_watts']); ?> W</td><td><b><?php echo _l('solar_pro_system_price'); ?></b><br><?php echo app_format_money($analysis['system_price'],get_base_currency()); ?></td></tr></table><br>
<h3><?php echo _l('solar_pro_payment_savings'); ?></h3><table cellpadding="6" border="1"><tr><th><?php echo _l('solar_pro_est_monthly_payment'); ?></th><th><?php echo _l('solar_pro_monthly_savings'); ?></th><th><?php echo _l('solar_pro_annual_savings'); ?></th><th>APR / <?php echo _l('solar_pro_term'); ?></th></tr><tr><td><?php echo app_format_money($finance['monthly_payment'],get_base_currency()); ?></td><td><?php echo app_format_money($finance['monthly_savings'],get_base_currency()); ?></td><td><?php echo app_format_money($finance['annual_savings'],get_base_currency()); ?></td><td><?php echo number_format($finance['apr_pct'],2); ?>% / <?php echo (int)$finance['term_years']; ?>y</td></tr></table><br>
